fn unary_sign_call(name: &str, argument: Expression) -> Expression {
    let field = crate::builtin_op::infer_unary_op_type(name, &argument)
        .unwrap_or_else(|| argument.static_type().unwrap().clone());
    call(name, field, vec![argument])
}
