#[test]
fn misc_native_sources_keep_types_flags_phases_returns_context_and_output_prefixes() {
    let returns = [
        ty(),
        ty().with_unsigned(true),
        real_ty(),
        FieldType::new(FieldTypeCode::Float),
        string_ty(),
        FieldType::new(FieldTypeCode::NewDecimal)
            .with_flen(65)
            .with_decimal(6),
        FieldType::new(FieldTypeCode::Date),
        FieldType::new(FieldTypeCode::Datetime).with_decimal(6),
        FieldType::new(FieldTypeCode::Duration).with_decimal(6),
        FieldType::new(FieldTypeCode::Json),
        FieldType::new(FieldTypeCode::VectorFloat32),
    ];
    for (field, values) in misc_native_source_types() {
        for ret in &returns {
            for name in crate::tikv::misc_value_tests::NAMES {
                let optional = matches!(name, "UUID_TO_BIN" | "BIN_TO_UUID");
                for position in 0..3 {
                    let schema = if field.code() == FieldTypeCode::NewDate {
                        vec![]
                    } else {
                        vec![field.clone()]
                    };
                    let rows = if schema.is_empty() {
                        vec![vec![]]
                    } else {
                        values.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>()
                    };
                    let value = if position == 0 || schema.is_empty() {
                        literal(values.last().unwrap().clone(), field.clone())
                    } else {
                        typed_column(0, &field)
                    };
                    let value = if position == 2 {
                        call(
                            "if",
                            field.clone(),
                            vec![int(1), value, literal(Datum::Null, field.clone())],
                        )
                    } else {
                        value
                    };
                    let mut argsets = vec![vec![value.clone()]];
                    if optional {
                        for flag in [
                            null(),
                            int(0),
                            int(-1),
                            literal(Datum::new_string("1bad"), string_ty()),
                            literal(Datum::new_string("bad"), string_ty()),
                        ] {
                            argsets.push(vec![value.clone(), flag]);
                        }
                    }
                    let selection = (0..rows.len())
                        .chain([0, rows.len() - 1])
                        .collect::<Vec<_>>();
                    for args in argsets {
                        let root = call(name, ret.clone(), args);
                        for seed in 0..3 {
                            for level in 0..3 {
                                compare_wildcard_source(
                                    root.clone(),
                                    &schema,
                                    &rows,
                                    &selection,
                                    seed,
                                    level,
                                );
                            }
                        }
                    }
                }
                // Full declared flag kinds, including NULL data and real valid payloads.
                if optional {
                    for (flag_type, flags) in misc_native_source_types() {
                        if flag_type.code() == FieldTypeCode::NewDate {
                            continue;
                        }
                        for payload in [
                            Datum::Null,
                            if name == "BIN_TO_UUID" {
                                Datum::Bytes(vec![0; 16])
                            } else {
                                Datum::new_string("6ba7b810-9dad-11d1-80b4-00c04fd430c8")
                            },
                            Datum::new_string("bad"),
                        ] {
                            let first_ty = crate::tikv::misc_identity_value_tests::field(&payload);
                            let root = call(
                                name,
                                ret.clone(),
                                vec![literal(payload, first_ty), typed_column(0, &flag_type)],
                            );
                            let rows = flags.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>();
                            for level in 0..3 {
                                compare_wildcard_source(
                                    root.clone(),
                                    std::slice::from_ref(&flag_type),
                                    &rows,
                                    &[0, 1, 0, 1],
                                    1,
                                    level,
                                );
                            }
                        }
                    }
                }
            }
        }
    }
    // All child EXPRESSIONS remain eager, even when later body conversion
    // would stop at NULL/invalid UUID before reading the literal flag value.
    for name in ["UUID_TO_BIN", "BIN_TO_UUID"] {
        for first in [Datum::Null, Datum::new_string("bad")] {
            let field = crate::tikv::misc_identity_value_tests::field(&first);
            let root = call(
                name,
                string_ty(),
                vec![
                    literal(first, field),
                    call("abs", ty(), vec![int(i64::MIN)]),
                ],
            );
            compare_wildcard_source(root, &[], &[vec![]], &[0, 0], 0, 0);
        }
    }
    // A genuine computed malformed coefficient still reaches its original
    // body error/panic; a stored constant probes BEFORE all child expressions.
    for name in crate::tikv::misc_value_tests::NAMES {
        for computed in [false, true] {
            let field = FieldType::new(FieldTypeCode::NewDecimal);
            let mut first = literal(
                crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                field.clone(),
            );
            if computed {
                first = call(
                    "if",
                    field.clone(),
                    vec![int(1), first, literal(Datum::Null, field)],
                );
            }
            compare_wildcard_source(
                call(name, string_ty(), vec![first]),
                &[],
                &[vec![]],
                &[0],
                0,
                0,
            );
        }
    }
}

#[test]
fn misc_native_resource_failure_is_terminal_and_same_source_null_recovers() {
    for name in [
        "IS_UUID",
        "UUID_TO_BIN",
        "BIN_TO_UUID",
        "TIDB_SHARD",
        "VITESS_HASH",
    ] {
        let schema = [string_ty()];
        let rows = [
            vec![Datum::new_string("1".repeat(1 << 20))],
            vec![Datum::Null],
        ];
        let actual = suite(call(name, string_ty(), vec![typed_column(0, &schema[0])]));
        let mut ctx = crate::tikv::wildcard_value_tests::context(1, 0, 0);
        ctx.inner.reject = true;
        let mut input = chunk(&schema, &rows);
        input.set_sel(Some(vec![0]));
        let mut output = output_for(&string_ty());
        let mut native = crate::tikv::wildcard_value_tests::context(1, 0, 0);
        native.inner.reject = true;
        let expected = crate::tikv::misc_value::eval_refs(
            crate::tikv::misc_value::operation(name).unwrap(),
            &[&rows[0][0]],
            &native,
            usize::MAX,
        )
        .and_then(|value| coerce_function_result(name, Some(&string_ty()), value));
        match expected {
            Ok(value) => {
                actual
                    .run_with_tikv_batch(&ctx, &mut input, &mut output, &schema)
                    .unwrap();
                let mut expected = output_for(&string_ty());
                expected.append_datum(0, &value);
                assert_eq!(output.column(0), expected.column(0));
            }
            Err(expected) => {
                let crate::evaluator::EvaluatorError::Eval(got) = actual
                    .run_with_tikv_batch(&ctx, &mut input, &mut output, &schema)
                    .unwrap_err()
                else {
                    panic!("native SQL error")
                };
                assert_eq!(got, expected);
            }
        }
        assert_eq!(*ctx.inner.events.borrow(), *native.inner.events.borrow());
        let route = actual.batch_route_snapshot();
        assert_eq!((route.refusals, route.fallback), (0, 0));
        ctx.inner.events.borrow_mut().clear();
        input.set_sel(Some(vec![1]));
        let mut output = output_for(&string_ty());
        actual
            .run_with_tikv_batch(&ctx, &mut input, &mut output, &schema)
            .unwrap();
        assert!(output.column(0).is_null(0));
        let route = actual.batch_route_snapshot();
        assert_eq!((route.refusals, route.fallback), (0, 0));
        assert!(ctx.inner.events.borrow().is_empty());
    }
}

#[test]
fn misc_native_capabilities_callbacks_ignored_payloads_panics_and_recovery() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::local::{
        HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, HostTaskId,
        LocalHostServices,
    };
    use tidb_query_expr::NativeMiscOperation as O;
    struct C<'a> {
        store: &'a RefCell<NativeValueStore>,
        events: RefCell<Vec<String>>,
        panic_zone: Cell<bool>,
        level: Cell<usize>,
    }
    impl crate::Columns for C<'_> {
        fn get(&self, _: &[String]) -> Option<Datum> {
            panic!("no invented misc source")
        }
        fn ready_value_cache(&self) -> Option<&crate::tikv::ReadyValueCache> {
            panic!("retired misc Ready")
        }
        fn time_zone(&self) -> SessionTimeZone {
            drop(self.store.borrow_mut());
            self.events.borrow_mut().push("zone".into());
            assert!(
                !self.panic_zone.replace(false),
                "original misc zone callback panic"
            );
            SessionTimeZone::utc()
        }
        fn truncate_level(&self) -> crate::ErrorLevel {
            drop(self.store.borrow_mut());
            self.events.borrow_mut().push("level".into());
            match self.level.get() {
                0 => crate::ErrorLevel::Warn,
                1 => crate::ErrorLevel::Error,
                _ => crate::ErrorLevel::Ignore,
            }
        }
        fn append_warning(&self, code: u16, message: &str) {
            drop(self.store.borrow_mut());
            self.events
                .borrow_mut()
                .push(format!("warning:{code}:{message}"));
        }
    }
    fn outcome(f: impl FnOnce() -> std::result::Result<Datum, EvalError>) -> Vec<u8> {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(Ok(v)) => format!("VALUE:{v:?}").into_bytes(),
            Ok(Err(e)) => format!("ERROR:{e:?}").into_bytes(),
            Err(p) => format!(
                "PANIC:{:?}",
                p.downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| p.downcast_ref::<&str>().copied())
            )
            .into_bytes(),
        }
    }
    for role in [NativeValueRole::Output, NativeValueRole::CharInput] {
        for name in crate::tikv::misc_value_tests::NAMES {
            let op = crate::tikv::misc_value::operation(name).unwrap();
            for arity in [1usize, 2].into_iter().filter(|n| op.accepts_arity(*n)) {
                let field = projected(&native_bytes_type(), true).unwrap();
                let args = vec![field.clone(); arity];
                let catalog = HostCatalog::for_sql_batch(vec![(
                    SqlBatchHostOperation::MiscNative {
                        operation: op,
                        arity: arity as u8,
                    },
                    HostSignature {
                        arg_types: args.clone().into_boxed_slice(),
                        return_type: field.clone(),
                    },
                )])
                .unwrap();
                let slot = catalog.slot(0).unwrap();
                let metadata = [NativeHostMetadata::Arguments(hosts::NativeArguments {
                    arguments: ((3..3 + arity).collect::<Vec<_>>().into_boxed_slice()).into(),
                    kernel: hosts::NativeArgumentKernel::Misc {
                        operation: op,
                        probe: None,
                    },
                    result_type: Some(string_ty()),
                    output_node: 2,
                    output_role: Some(role),
                })];
                let store = RefCell::new(NativeValueStore::new().unwrap());
                store.borrow_mut().begin_window().unwrap();
                let row = InputRow {
                    occurrence: 0,
                    input_row: 0,
                };
                let insert = |v: &Datum, role, node, row| {
                    store
                        .borrow_mut()
                        .insert_clone(v, role, NativeValueOrigin { node, row })
                        .unwrap()
                };
                let stale = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
                store.borrow_mut().begin_window().unwrap();
                let foreign = RefCell::new(NativeValueStore::new().unwrap());
                foreign.borrow_mut().begin_window().unwrap();
                let foreign_token = foreign
                    .borrow_mut()
                    .insert_clone(
                        &Datum::Null,
                        NativeValueRole::CharInput,
                        NativeValueOrigin { node: 3, row },
                    )
                    .unwrap();
                let context = C {
                    store: &store,
                    events: RefCell::new(vec![]),
                    panic_zone: Cell::new(false),
                    level: Cell::new(0),
                };
                let mut provider = NativeBatchHosts::new(catalog, &metadata, &context)
                    .with_native_values(Some(&store));
                let mut ctx = EvalContext::default();
                let begin = |p: &mut NativeBatchHosts<'_>, c: &mut EvalContext| {
                    let HostStart::Pending { task, .. } = p
                        .start(
                            c,
                            HostInvocation {
                                slot,
                                row,
                                arg_types: &args,
                                return_type: &field,
                            },
                        )
                        .unwrap()
                    else {
                        panic!()
                    };
                    task
                };
                let reply = |p: &mut NativeBatchHosts<'_>,
                             c: &mut EvalContext,
                             t: &HostTaskId,
                             index,
                             token: Option<Vec<u8>>| {
                    p.resume(
                        c,
                        t,
                        HostArgReply {
                            index,
                            field_type: &field,
                            values: &VectorValue::from_scalar(&ScalarValue::Bytes(token), 1),
                        },
                    )
                };
                for index in 0..arity {
                    let mut corrupt =
                        insert(&Datum::Null, NativeValueRole::CharInput, 3 + index, row);
                    corrupt[0] ^= 1;
                    for bad in [
                        None,
                        Some(corrupt),
                        Some(stale.clone()),
                        Some(foreign_token.clone()),
                        Some(insert(
                            &Datum::Null,
                            NativeValueRole::Output,
                            3 + index,
                            row,
                        )),
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 99, row)),
                        Some(insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3 + index,
                            InputRow {
                                occurrence: 1,
                                input_row: 0,
                            },
                        )),
                        Some(insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3 + index,
                            InputRow {
                                occurrence: 0,
                                input_row: 1,
                            },
                        )),
                    ] {
                        context.events.borrow_mut().clear();
                        let task = begin(&mut provider, &mut ctx);
                        for prefix in 0..index {
                            assert!(matches!(
                                reply(
                                    &mut provider,
                                    &mut ctx,
                                    &task,
                                    prefix,
                                    Some(
                                        insert(
                                            &Datum::Null,
                                            NativeValueRole::CharInput,
                                            3 + prefix,
                                            row
                                        )
                                        .to_vec()
                                    )
                                ),
                                Ok(HostStep::NeedArg(_))
                            ));
                        }
                        assert!(matches!(
                            reply(
                                &mut provider,
                                &mut ctx,
                                &task,
                                index,
                                bad.map(|bytes| bytes.to_vec())
                            ),
                            Err(LocalError::BindingContract(_))
                        ));
                        assert!(context.events.borrow().is_empty());
                        assert!(provider.take_native_error().is_none());
                        provider.cancel(&task);
                        provider.cancel(&task);
                    }
                }
                let valid = if op == O::BinToUuid {
                    Datum::Bytes(vec![0; 16])
                } else if matches!(op, O::TidbShard | O::VitessHash) {
                    Datum::Int(7)
                } else {
                    Datum::new_string("6ba7b810-9dad-11d1-80b4-00c04fd430c8")
                };
                let mut cases = vec![
                    vec![valid.clone(); arity],
                    vec![Datum::Null; arity],
                    vec![Datum::new_string("bad"); arity],
                    vec![Datum::Bytes(vec![255]); arity],
                    vec![crate::tikv::misc_identity_value_tests::extra_values().remove(4); arity],
                ];
                if arity == 2 {
                    for first in [valid.clone(), Datum::Null, Datum::new_string("bad")] {
                        for flag in [
                            Datum::new_string("1bad"),
                            Datum::Bytes(vec![255]),
                            Datum::Enum(
                                tidb_datatype::MysqlEnum::new(vec![255; 1 << 20], 1),
                                Collation::Utf8Mb4ZhPinyinTiDbAsCs,
                            ),
                            Datum::VectorFloat32(VectorFloat32::init(1 << 18)),
                        ] {
                            cases.push(vec![first.clone(), flag]);
                        }
                    }
                    if op == O::UuidToBin {
                        cases.push(vec![Datum::Null, Datum::Bytes(vec![255; 1 << 20])]);
                    }
                }
                if matches!(op, O::TidbShard | O::VitessHash) {
                    cases.extend([
                        vec![Datum::VectorFloat32(VectorFloat32::init(1 << 18))],
                        vec![Datum::Raw(vec![255; 1 << 20])],
                        vec![Datum::MinNotNull],
                    ]);
                }
                for values in cases {
                    for level in 0..3 {
                        context.level.set(level);
                        context.events.borrow_mut().clear();
                        let task = begin(&mut provider, &mut ctx);
                        let actual = outcome(|| {
                            let mut last = None;
                            for (i, v) in values.iter().enumerate() {
                                let step = reply(
                                    &mut provider,
                                    &mut ctx,
                                    &task,
                                    i,
                                    Some(
                                        insert(v, NativeValueRole::CharInput, 3 + i, row).to_vec(),
                                    ),
                                );
                                if i + 1 < arity {
                                    assert!(matches!(step, Ok(HostStep::NeedArg(_))));
                                    assert!(context.events.borrow().is_empty());
                                } else {
                                    last = Some(step);
                                }
                            }
                            match last.unwrap() {
                                Ok(HostStep::Ready(v)) => {
                                    let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0)
                                    else {
                                        panic!()
                                    };
                                    Ok(store
                                        .borrow()
                                        .get(token, role, NativeValueOrigin { node: 2, row })
                                        .unwrap()
                                        .clone())
                                }
                                Err(_) => Err(provider
                                    .take_native_error()
                                    .expect("small/demanded bounded misc result")),
                                _ => panic!(),
                            }
                        });
                        let events = context.events.borrow().clone();
                        context.events.borrow_mut().clear();
                        let expected = outcome(|| {
                            crate::builtin_ext::misc::dispatch_in(name, &values, &context)
                                .unwrap()
                                .and_then(|v| {
                                    coerce_function_result(op.name(), Some(&string_ty()), v)
                                })
                        });
                        assert_eq!(actual, expected, "{name} arity={arity} level={level}");
                        assert_eq!(events, *context.events.borrow());
                        let _ = provider.take_native_error();
                        assert!(reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            arity - 1,
                            Some(
                                insert(
                                    &Datum::Null,
                                    NativeValueRole::CharInput,
                                    3 + arity - 1,
                                    row
                                )
                                .to_vec()
                            )
                        )
                        .is_err());
                        provider.cancel(&task);
                    }
                }
                // A real callback panic consumes its host phase, and later calls recover.
                if matches!(op, O::TidbShard | O::VitessHash) {
                    context.panic_zone.set(true);
                    let task = begin(&mut provider, &mut ctx);
                    assert!(
                        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            0,
                            Some(
                                insert(&Datum::Int(7), NativeValueRole::CharInput, 3, row).to_vec()
                            )
                        )))
                        .is_err()
                    );
                    assert!(reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                    )
                    .is_err());
                    provider.cancel(&task);
                    let task = begin(&mut provider, &mut ctx);
                    assert!(matches!(
                        reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            0,
                            Some(
                                insert(&Datum::Int(9), NativeValueRole::CharInput, 3, row).to_vec()
                            )
                        ),
                        Ok(HostStep::Ready(_))
                    ));
                }
            }
        }
    }
}

#[test]
fn misc_native_hash_unused_vector_payload_keeps_original_small_body_work() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::{
        local::{
            HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, LocalHostServices,
        },
        NativeMiscOperation as O,
    };
    for op in [O::TidbShard, O::VitessHash] {
        let field = projected(&native_bytes_type(), true).unwrap();
        let args = [field.clone()];
        let catalog = HostCatalog::for_sql_batch(vec![(
            SqlBatchHostOperation::MiscNative {
                operation: op,
                arity: 1,
            },
            HostSignature {
                arg_types: args.clone().into(),
                return_type: field.clone(),
            },
        )])
        .unwrap();
        let slot = catalog.slot(0).unwrap();
        let metadata = [NativeHostMetadata::Arguments(hosts::NativeArguments {
            arguments: (vec![3].into_boxed_slice()).into(),
            kernel: hosts::NativeArgumentKernel::Misc {
                operation: op,
                probe: None,
            },
            result_type: Some(ty().with_unsigned(true)),
            output_node: 2,
            output_role: Some(NativeValueRole::Output),
        })];
        let store = RefCell::new(NativeValueStore::new().unwrap());
        store.borrow_mut().begin_window().unwrap();
        let row = InputRow {
            occurrence: 0,
            input_row: 0,
        };
        let value = Datum::VectorFloat32(VectorFloat32::init(1 << 18));
        let token = store
            .borrow_mut()
            .insert_clone(
                &value,
                NativeValueRole::CharInput,
                NativeValueOrigin { node: 3, row },
            )
            .unwrap();
        let mut provider = NativeBatchHosts::new(catalog, &metadata, &crate::NoColumns)
            .with_native_values(Some(&store));
        let mut ctx = EvalContext::default();
        let HostStart::Pending { task, .. } = provider
            .start(
                &mut ctx,
                HostInvocation {
                    slot,
                    row,
                    arg_types: &args,
                    return_type: &field,
                },
            )
            .unwrap()
        else {
            panic!()
        };
        let result = provider.resume(
            &mut ctx,
            &task,
            HostArgReply {
                index: 0,
                field_type: &field,
                values: &VectorValue::from_scalar(&ScalarValue::Bytes(Some(token.to_vec())), 1),
            },
        );
        let actual = match result {
            Ok(HostStep::Ready(out)) => {
                let ScalarValueRef::Bytes(Some(token)) = out.get_scalar_ref(0) else {
                    panic!()
                };
                Ok(store
                    .borrow()
                    .get(
                        token,
                        NativeValueRole::Output,
                        NativeValueOrigin { node: 2, row },
                    )
                    .unwrap()
                    .clone())
            }
            Err(_) => Err(provider.take_native_error().unwrap()),
            _ => panic!(),
        };
        let expected = crate::builtin_ext::misc::dispatch_in(
            if op == O::TidbShard {
                "TIDB_SHARD"
            } else {
                "VITESS_HASH"
            },
            &[value],
            &crate::NoColumns,
        )
        .unwrap();
        assert_eq!(actual, expected, "ignored vector payload {op:?}");
    }
}

#[test]
fn native_byte_unary_sources_do_not_fallback() {
    let mut failures = vec![];
    for name in crate::tikv::byte_unary_value_tests::NAMES {
        let v = Datum::Bytes(b" x ".to_vec());
        let ty = crate::tikv::misc_identity_value_tests::field(&v);
        let actual = suite(call(name, string_ty(), vec![literal(v, ty)]));
        let mut input = chunk(&[], &[vec![]]);
        let mut output = output_for(&string_ty());
        let _ = actual.run_with_tikv_batch(&crate::NoColumns, &mut input, &mut output, &[]);
        let route = actual.batch_route_snapshot();
        if (route.refusals, route.fallback) != (0, 0) {
            failures.push((name, route));
        }
    }
    assert!(failures.is_empty(), "byte unary source {failures:?}");
}

#[test]
fn byte_unary_sources_keep_signature_casts_raw_bytes_binary_results_types_context_and_prefixes() {
    let returns = [
        ty(),
        ty().with_unsigned(true),
        real_ty(),
        FieldType::new(FieldTypeCode::Float),
        string_ty(),
        FieldType::new(FieldTypeCode::NewDecimal)
            .with_flen(65)
            .with_decimal(6),
        FieldType::new(FieldTypeCode::Date),
        FieldType::new(FieldTypeCode::Datetime).with_decimal(6),
        FieldType::new(FieldTypeCode::Duration).with_decimal(6),
        FieldType::new(FieldTypeCode::Json),
        FieldType::new(FieldTypeCode::VectorFloat32),
    ];
    let mut sources = misc_native_source_types();
    for (field, values) in &mut sources {
        if field.code() == FieldTypeCode::VarString {
            values.extend([
                Datum::new_string("  65  "),
                Datum::Bytes(b"  \xff  ".to_vec()),
                Datum::new_string("\t x\n"),
                Datum::new_string("\u{a0}中\u{2003}"),
            ]);
        }
    }
    for (field, values) in sources {
        for ret in &returns {
            for name in crate::tikv::byte_unary_value_tests::NAMES {
                for position in 0..3 {
                    let schema = if field.code() == FieldTypeCode::NewDate {
                        vec![]
                    } else {
                        vec![field.clone()]
                    };
                    let rows = if schema.is_empty() {
                        vec![vec![]]
                    } else {
                        values.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>()
                    };
                    let value = if position == 0 || schema.is_empty() {
                        literal(values.last().unwrap().clone(), field.clone())
                    } else {
                        typed_column(0, &field)
                    };
                    let value = if position == 2 {
                        call(
                            "if",
                            field.clone(),
                            vec![int(1), value, literal(Datum::Null, field.clone())],
                        )
                    } else {
                        value
                    };
                    let selection = (0..rows.len())
                        .rev()
                        .chain([0, rows.len() - 1, 0])
                        .collect::<Vec<_>>();
                    for profile in 0..3 {
                        for level in 0..3 {
                            compare_wildcard_source(
                                call(name, ret.clone(), vec![value.clone()]),
                                &schema,
                                &rows,
                                &selection,
                                profile,
                                level,
                            );
                        }
                    }
                }
            }
        }
    }
    for name in crate::tikv::byte_unary_value_tests::NAMES {
        compare_wildcard_source(
            call(
                name,
                string_ty(),
                vec![call("abs", ty(), vec![int(i64::MIN)])],
            ),
            &[],
            &[vec![]],
            &[0, 0],
            0,
            0,
        );
        for computed in [false, true] {
            let field = FieldType::new(FieldTypeCode::NewDecimal);
            let mut value = literal(
                crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                field.clone(),
            );
            if computed {
                value = call(
                    "if",
                    field.clone(),
                    vec![int(1), value, literal(Datum::Null, field)],
                );
            }
            compare_wildcard_source(
                call(name, string_ty(), vec![value]),
                &[],
                &[vec![]],
                &[0],
                0,
                0,
            );
        }
    }
}

#[test]
fn byte_unary_capabilities_consumption_panics_resources_ignored_suffix_and_recovery() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::{
        local::{
            HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, HostTaskId,
            LocalHostServices,
        },
        NativeByteUnaryOperation as O,
    };
    struct C;
    impl crate::Columns for C {
        fn get(&self, _: &[String]) -> Option<Datum> {
            panic!("no invented byte unary source")
        }
        fn ready_value_cache(&self) -> Option<&crate::tikv::ReadyValueCache> {
            panic!("retired byte unary Ready")
        }
        fn time_zone(&self) -> SessionTimeZone {
            panic!("pure byte unary must not read zone")
        }
        fn truncate_level(&self) -> crate::ErrorLevel {
            panic!("pure byte unary must not read truncation policy")
        }
        fn append_warning(&self, _: u16, _: &str) {
            panic!("pure byte unary must not invent warning")
        }
    }
    fn outcome(f: impl FnOnce() -> std::result::Result<Datum, EvalError>) -> Vec<u8> {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(Ok(v)) => format!("VALUE:{v:?}").into_bytes(),
            Ok(Err(e)) => format!("ERROR:{e:?}").into_bytes(),
            Err(p) => format!(
                "PANIC:{:?}",
                p.downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| p.downcast_ref::<&str>().copied())
            )
            .into_bytes(),
        }
    }
    let mut bad_caps = 0;
    for role in [NativeValueRole::Output, NativeValueRole::CharInput] {
        for op in [O::Ascii, O::LTrim, O::RTrim] {
            let field = projected(&native_bytes_type(), true).unwrap();
            let args = [field.clone()];
            let ret = if op == O::Ascii { ty() } else { string_ty() };
            let catalog = HostCatalog::for_sql_batch(vec![(
                SqlBatchHostOperation::ByteUnaryNative(op),
                HostSignature {
                    arg_types: args.clone().into(),
                    return_type: field.clone(),
                },
            )])
            .unwrap();
            let slot = catalog.slot(0).unwrap();
            let metadata = [NativeHostMetadata::Arguments(hosts::NativeArguments {
                arguments: (3).into(),
                kernel: hosts::NativeArgumentKernel::ByteUnary {
                    operation: op,
                    probe: None,
                },
                result_type: Some(ret.clone()),
                output_node: 2,
                output_role: Some(role),
            })];
            let store = RefCell::new(NativeValueStore::new().unwrap());
            store.borrow_mut().begin_window().unwrap();
            let row = InputRow {
                occurrence: 0,
                input_row: 0,
            };
            let insert = |v: &Datum, role, node, row| {
                store
                    .borrow_mut()
                    .insert_clone(v, role, NativeValueOrigin { node, row })
                    .unwrap()
            };
            let stale = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
            store.borrow_mut().begin_window().unwrap();
            let foreign = RefCell::new(NativeValueStore::new().unwrap());
            foreign.borrow_mut().begin_window().unwrap();
            let foreign_token = foreign
                .borrow_mut()
                .insert_clone(
                    &Datum::Null,
                    NativeValueRole::CharInput,
                    NativeValueOrigin { node: 3, row },
                )
                .unwrap();
            let context = C;
            let mut provider = NativeBatchHosts::new(catalog, &metadata, &context)
                .with_native_values(Some(&store));
            let mut ctx = EvalContext::default();
            let begin = |p: &mut NativeBatchHosts<'_>, c: &mut EvalContext| {
                let HostStart::Pending { task, request } = p
                    .start(
                        c,
                        HostInvocation {
                            slot,
                            row,
                            arg_types: &args,
                            return_type: &field,
                        },
                    )
                    .unwrap()
                else {
                    panic!()
                };
                assert_eq!(request.index, 0);
                task
            };
            let reply = |p: &mut NativeBatchHosts<'_>,
                         c: &mut EvalContext,
                         t: &HostTaskId,
                         index,
                         token: Option<Vec<u8>>| {
                p.resume(
                    c,
                    t,
                    HostArgReply {
                        index,
                        field_type: &field,
                        values: &VectorValue::from_scalar(&ScalarValue::Bytes(token), 1),
                    },
                )
            };
            let mut corrupt = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
            corrupt[0] ^= 1;
            for bad in [
                None,
                Some(corrupt),
                Some(stale),
                Some(foreign_token),
                Some(insert(&Datum::Null, NativeValueRole::Output, 3, row)),
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 99, row)),
                Some(insert(
                    &Datum::Null,
                    NativeValueRole::CharInput,
                    3,
                    InputRow {
                        occurrence: 1,
                        input_row: 0,
                    },
                )),
                Some(insert(
                    &Datum::Null,
                    NativeValueRole::CharInput,
                    3,
                    InputRow {
                        occurrence: 0,
                        input_row: 1,
                    },
                )),
            ] {
                let task = begin(&mut provider, &mut ctx);
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        bad.map(|bytes| bytes.to_vec())
                    ),
                    Err(LocalError::BindingContract(_))
                ));
                assert!(provider.take_native_error().is_none());
                provider.cancel(&task);
                provider.cancel(&task);
                bad_caps += 1;
            }
            let task = begin(&mut provider, &mut ctx);
            assert!(reply(
                &mut provider,
                &mut ctx,
                &task,
                1,
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
            )
            .is_err());
            provider.cancel(&task);
            bad_caps += 1;
            let mut cases = vec![
                Datum::Null,
                Datum::Int(7),
                Datum::Real(f64::NAN),
                Datum::Bytes(b"  \xff\0 ".to_vec()),
                Datum::new_string(b"  \xff\0 "),
                Datum::new_string("\u{a0}中\u{2003}"),
                Datum::Bit(tidb_datatype::BinaryLiteral::from(vec![255])),
                Datum::Enum(
                    tidb_datatype::MysqlEnum::new("  65  ", 1),
                    Collation::Binary,
                ),
                Datum::Set(
                    tidb_datatype::MysqlSet::new("  65  ", 3),
                    Collation::Utf8Mb4Bin,
                ),
                crate::tikv::misc_identity_value_tests::extra_values().remove(4),
            ];
            if op == O::Ascii {
                cases.push(Datum::Bytes(vec![255; 1 << 20]));
                cases.push(Datum::Raw(vec![255; 1 << 20]));
            }
            for value in cases {
                let task = begin(&mut provider, &mut ctx);
                let token = insert(&value, NativeValueRole::CharInput, 3, row);
                let actual = outcome(|| {
                    match reply(&mut provider, &mut ctx, &task, 0, Some(token.to_vec())) {
                        Ok(HostStep::Ready(v)) => {
                            let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0) else {
                                panic!()
                            };
                            Ok(store
                                .borrow()
                                .get(token, role, NativeValueOrigin { node: 2, row })
                                .unwrap()
                                .clone())
                        }
                        Err(_) => Err(provider
                            .take_native_error()
                            .expect("bounded byte unary small result")),
                        _ => panic!(),
                    }
                });
                let expected = outcome(|| {
                    let value = if op == O::Ascii {
                        value.clone()
                    } else {
                        crate::cast::cast_arg_as_string(&value, None, &context)?
                    };
                    crate::tikv::byte_unary_value_tests::direct(
                        &op.name().to_ascii_uppercase(),
                        value,
                        &context,
                    )
                    .and_then(|v| coerce_function_result(op.name(), Some(&ret), v))
                });
                assert_eq!(actual, expected, "byte unary provider {op:?} role={role:?}");
                assert!(reply(
                    &mut provider,
                    &mut ctx,
                    &task,
                    0,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                )
                .is_err());
                let _ = provider.take_native_error();
                provider.cancel(&task);
                provider.cancel(&task);
            }
            let task = begin(&mut provider, &mut ctx);
            let HostStep::Ready(v) = reply(
                &mut provider,
                &mut ctx,
                &task,
                0,
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec()),
            )
            .unwrap() else {
                panic!()
            };
            let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0) else {
                panic!()
            };
            assert!(store
                .borrow()
                .get(token, role, NativeValueOrigin { node: 2, row })
                .unwrap()
                .is_null());
            provider.cancel(&task);
        }
    }
    assert_eq!(bad_caps, 54);
}

#[test]
fn native_crypto_actual_sources_do_not_fallback() {
    let mut failures = vec![];
    for name in crate::tikv::crypto_value_tests::NAMES {
        let mut args = vec![literal(Datum::new_string("value"), string_ty())];
        if matches!(name, "ENCODE" | "DECODE") {
            args.push(literal(Datum::new_string("password"), string_ty()));
        }
        let actual = suite(call(name, string_ty(), args));
        let mut input = chunk(&[], &[vec![]]);
        let mut output = output_for(&string_ty());
        let _ = actual.run_with_tikv_batch(&crate::NoColumns, &mut input, &mut output, &[]);
        let route = actual.batch_route_snapshot();
        if (route.refusals, route.fallback) != (0, 0) {
            failures.push((name, route));
        }
    }
    assert!(failures.is_empty(), "crypto actual source {failures:?}");
}

#[test]
fn crypto_actual_sources_keep_types_returns_eager_children_context_and_prefixes() {
    let returns = [
        ty(),
        ty().with_unsigned(true),
        real_ty(),
        FieldType::new(FieldTypeCode::Float),
        string_ty(),
        FieldType::new(FieldTypeCode::NewDecimal)
            .with_flen(65)
            .with_decimal(6),
        FieldType::new(FieldTypeCode::Date),
        FieldType::new(FieldTypeCode::Datetime).with_decimal(6),
        FieldType::new(FieldTypeCode::Duration).with_decimal(6),
        FieldType::new(FieldTypeCode::Json),
        FieldType::new(FieldTypeCode::VectorFloat32),
    ];
    for (field, values) in misc_native_source_types() {
        for ret in &returns {
            for name in crate::tikv::crypto_value_tests::NAMES
                .into_iter()
                .chain(crate::tikv::digest_value_tests::NAMES)
            {
                let arity = crate::tikv::crypto_value::operation(name).unwrap().arity();
                for argument in 0..arity {
                    for position in 0..3 {
                        let schema = if field.code() == FieldTypeCode::NewDate {
                            vec![]
                        } else {
                            vec![field.clone()]
                        };
                        let rows = if schema.is_empty() {
                            vec![vec![]]
                        } else {
                            values.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>()
                        };
                        let value = if position == 0 || schema.is_empty() {
                            literal(values.last().unwrap().clone(), field.clone())
                        } else {
                            typed_column(0, &field)
                        };
                        let value = if position == 2 {
                            call(
                                "if",
                                field.clone(),
                                vec![int(1), value, literal(Datum::Null, field.clone())],
                            )
                        } else {
                            value
                        };
                        let mut args =
                            vec![literal(Datum::new_string("value"), string_ty()); arity];
                        args[argument] = value;
                        let selection = (0..rows.len())
                            .rev()
                            .chain([0, rows.len() - 1, 0])
                            .collect::<Vec<_>>();
                        for profile in 0..3 {
                            for level in 0..3 {
                                compare_wildcard_source(
                                    call(name, ret.clone(), args.clone()),
                                    &schema,
                                    &rows,
                                    &selection,
                                    profile,
                                    level,
                                );
                            }
                        }
                    }
                }
            }
        }
    }
    for name in crate::tikv::crypto_value_tests::NAMES
        .into_iter()
        .chain(crate::tikv::digest_value_tests::NAMES)
    {
        let arity = crate::tikv::crypto_value::operation(name).unwrap().arity();
        for argument in 0..arity {
            for computed in [false, true] {
                let field = FieldType::new(FieldTypeCode::NewDecimal);
                let mut value = literal(
                    crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                    field.clone(),
                );
                if computed {
                    value = call(
                        "if",
                        field.clone(),
                        vec![int(1), value, literal(Datum::Null, field)],
                    );
                }
                let mut args = vec![literal(Datum::new_string("value"), string_ty()); arity];
                args[argument] = value;
                compare_wildcard_source(
                    call(name, string_ty(), args),
                    &[],
                    &[vec![]],
                    &[0, 0],
                    0,
                    0,
                );
            }
        }
        for payload in [
            Datum::Bytes(vec![255, 0]),
            Datum::Raw(vec![255]),
            Datum::MinNotNull,
            Datum::MaxValue,
        ] {
            let mut args = vec![literal(Datum::new_string(""), string_ty()); arity];
            args[0] = literal(payload, string_ty());
            let root = call(name, string_ty(), args);
            compare_wildcard_source(
                call("cast_char", string_ty(), vec![root]),
                &[],
                &[vec![]],
                &[0, 0],
                0,
                0,
            );
        }
        for argument in 0..arity {
            let mut args = vec![literal(Datum::Null, string_ty()); arity];
            args[argument] = call("abs", ty(), vec![int(i64::MIN)]);
            // NULL data cannot suppress an error in the eager password expression.
            compare_wildcard_source(call(name, string_ty(), args), &[], &[vec![]], &[0, 0], 0, 0);
        }
    }
}

#[test]
fn crypto_actual_capabilities_warning_callbacks_consumption_and_ignored_password() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::{
        local::{
            HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, HostTaskId,
            LocalHostServices,
        },
        NativeCryptoOperation as O,
    };
    struct C<'a> {
        store: &'a RefCell<NativeValueStore>,
        events: RefCell<Vec<String>>,
        warning_action: Cell<u8>,
    }
    impl crate::Columns for C<'_> {
        fn get(&self, _: &[String]) -> Option<Datum> {
            panic!("no invented crypto source")
        }
        fn ready_value_cache(&self) -> Option<&crate::tikv::ReadyValueCache> {
            panic!("retired crypto Ready")
        }
        fn time_zone(&self) -> SessionTimeZone {
            panic!("pure crypto does not read zone")
        }
        fn truncate_level(&self) -> crate::ErrorLevel {
            panic!("pure crypto does not read truncation policy")
        }
        fn append_warning(&self, code: u16, message: &str) {
            // A real context callback must be free to borrow the store exclusively.
            let mut values = self.store.borrow_mut();
            self.events
                .borrow_mut()
                .push(format!("warning:{code}:{message}"));
            match self.warning_action.replace(0) {
                1 => panic!("original PASSWORD warning panic"),
                2 => values.begin_window().unwrap(),
                _ => (),
            }
        }
    }
    fn outcome(f: impl FnOnce() -> std::result::Result<Datum, EvalError>) -> String {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(v) => format!("{v:?}"),
            Err(p) => format!(
                "PANIC:{:?}",
                p.downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| p.downcast_ref::<&str>().copied())
            ),
        }
    }
    let mut rejected = 0;
    for role in [NativeValueRole::Output, NativeValueRole::CharInput] {
        for op in [
            O::Sm3,
            O::Password,
            O::Encode,
            O::Decode,
            O::Md5,
            O::Sha,
            O::Sha1,
            O::Sha2,
        ] {
            let arity = op.arity();
            let field = projected(&native_bytes_type(), true).unwrap();
            let args = vec![field.clone(); arity];
            let catalog = HostCatalog::for_sql_batch(vec![(
                SqlBatchHostOperation::CryptoNative(op),
                HostSignature {
                    arg_types: args.clone().into_boxed_slice(),
                    return_type: field.clone(),
                },
            )])
            .unwrap();
            let slot = catalog.slot(0).unwrap();
            let metadata = [NativeHostMetadata::Arguments(hosts::NativeArguments {
                arguments: ((3..3 + arity).collect::<Vec<_>>().into_boxed_slice()).into(),
                kernel: hosts::NativeArgumentKernel::Crypto {
                    operation: op,
                    probe: None,
                },
                result_type: Some(string_ty()),
                output_node: 2,
                output_role: Some(role),
            })];
            let store = RefCell::new(NativeValueStore::new().unwrap());
            store.borrow_mut().begin_window().unwrap();
            let row = InputRow {
                occurrence: 0,
                input_row: 0,
            };
            let insert = |v: &Datum, role, node, row| {
                store
                    .borrow_mut()
                    .insert_clone(v, role, NativeValueOrigin { node, row })
                    .unwrap()
            };
            let stale = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
            store.borrow_mut().begin_window().unwrap();
            let mut foreign = NativeValueStore::new().unwrap();
            foreign.begin_window().unwrap();
            let foreign_token = foreign
                .insert_clone(
                    &Datum::Null,
                    NativeValueRole::CharInput,
                    NativeValueOrigin { node: 3, row },
                )
                .unwrap();
            let context = C {
                store: &store,
                events: RefCell::new(vec![]),
                warning_action: Cell::new(0),
            };
            let mut provider = NativeBatchHosts::new(catalog, &metadata, &context)
                .with_native_values(Some(&store));
            let mut ctx = EvalContext::default();
            let begin = |p: &mut NativeBatchHosts<'_>, c: &mut EvalContext| {
                let HostStart::Pending { task, request } = p
                    .start(
                        c,
                        HostInvocation {
                            slot,
                            row,
                            arg_types: &args,
                            return_type: &field,
                        },
                    )
                    .unwrap()
                else {
                    panic!()
                };
                assert_eq!(request.index, 0);
                task
            };
            let reply = |p: &mut NativeBatchHosts<'_>,
                         c: &mut EvalContext,
                         t: &HostTaskId,
                         index,
                         token: Option<Vec<u8>>| {
                p.resume(
                    c,
                    t,
                    HostArgReply {
                        index,
                        field_type: &field,
                        values: &VectorValue::from_scalar(&ScalarValue::Bytes(token), 1),
                    },
                )
            };
            for index in 0..arity {
                let good = insert(&Datum::Null, NativeValueRole::CharInput, 3 + index, row);
                let mut corrupt = good.clone();
                corrupt[0] ^= 1;
                let mut short = good.to_vec();
                short.pop();
                let mut long = good.to_vec();
                long.push(0);
                for bad in [
                    None,
                    Some((corrupt).to_vec()),
                    Some((short).to_vec()),
                    Some((long).to_vec()),
                    Some((stale.clone()).to_vec()),
                    Some((foreign_token.clone()).to_vec()),
                    Some((insert(&Datum::Null, NativeValueRole::Output, 3 + index, row)).to_vec()),
                    Some((insert(&Datum::Null, NativeValueRole::CharInput, 99, row)).to_vec()),
                    Some(
                        (insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3 + index,
                            InputRow {
                                occurrence: 1,
                                input_row: 0,
                            },
                        ))
                        .to_vec(),
                    ),
                    Some(
                        (insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3 + index,
                            InputRow {
                                occurrence: 0,
                                input_row: 1,
                            },
                        ))
                        .to_vec(),
                    ),
                ] {
                    context.events.borrow_mut().clear();
                    let task = begin(&mut provider, &mut ctx);
                    for prefix in 0..index {
                        assert!(matches!(
                            reply(
                                &mut provider,
                                &mut ctx,
                                &task,
                                prefix,
                                Some(
                                    insert(
                                        &Datum::Null,
                                        NativeValueRole::CharInput,
                                        3 + prefix,
                                        row
                                    )
                                    .to_vec()
                                )
                            ),
                            Ok(HostStep::NeedArg(_))
                        ));
                    }
                    assert!(matches!(
                        reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            index,
                            bad.map(|bytes| bytes.to_vec())
                        ),
                        Err(LocalError::BindingContract(_))
                    ));
                    assert!(context.events.borrow().is_empty());
                    assert!(provider.take_native_error().is_none());
                    provider.cancel(&task);
                    provider.cancel(&task);
                    rejected += 1;
                }
            }
            let task = begin(&mut provider, &mut ctx);
            assert!(reply(
                &mut provider,
                &mut ctx,
                &task,
                arity,
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
            )
            .is_err());
            provider.cancel(&task);
            rejected += 1;
            let mut cases = vec![
                vec![Datum::Null; arity],
                vec![Datum::new_string(""); arity],
                vec![Datum::new_string("value"); arity],
                vec![Datum::Bytes(vec![255, 0]); arity],
                vec![Datum::Raw(vec![255]); arity],
                vec![Datum::Int(-7); arity],
                vec![Datum::MinNotNull; arity],
                vec![crate::tikv::misc_identity_value_tests::extra_values().remove(4); arity],
            ];
            if arity == 2 {
                for password in [
                    Datum::Bytes(vec![255; 1 << 20]),
                    Datum::VectorFloat32(VectorFloat32::init(1 << 18)),
                    Datum::Decimal(Decimal::from_raw_parts(false, vec![b'1'], u32::MAX, 1)),
                    crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                ] {
                    cases.push(vec![Datum::Null, password]);
                }
                cases.push(vec![Datum::new_string("value"), Datum::Null]);
            }
            if op == O::Sha2 {
                for length in [Datum::Int(128), Datum::Null] {
                    cases.push(vec![Datum::Bytes(vec![255; 1 << 20]), length]);
                }
                for length in [
                    Datum::Decimal(Decimal::from_raw_parts(false, vec![b'1'], u32::MAX, 0)),
                    Datum::Enum(
                        tidb_datatype::MysqlEnum::new(vec![255; 1 << 20], 256),
                        Collation::Utf8Mb4Bin,
                    ),
                    Datum::Set(
                        tidb_datatype::MysqlSet::new(vec![255; 1 << 20], 256),
                        Collation::Utf8Mb4Bin,
                    ),
                    Datum::BinaryLiteral(tidb_datatype::BinaryLiteral::from(vec![255; 1 << 20])),
                    Datum::Raw(vec![255; 1 << 20]),
                    Datum::VectorFloat32(VectorFloat32::init(1 << 18)),
                    Datum::Json(
                        BinaryJSON::parse(&format!("{{\"x\":\"{}\"}}", "x".repeat(1 << 20)))
                            .unwrap(),
                    ),
                ] {
                    cases.push(vec![Datum::new_string("value"), length]);
                }
            }
            for values in cases {
                context.events.borrow_mut().clear();
                let task = begin(&mut provider, &mut ctx);
                let actual = outcome(|| {
                    let mut last = None;
                    for (i, value) in values.iter().enumerate() {
                        let step = reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            i,
                            Some(insert(value, NativeValueRole::CharInput, 3 + i, row).to_vec()),
                        );
                        if i + 1 < arity {
                            assert!(matches!(step, Ok(HostStep::NeedArg(_))));
                            assert!(context.events.borrow().is_empty());
                        } else {
                            last = Some(step);
                        }
                    }
                    match last.unwrap() {
                        Ok(HostStep::Ready(v)) => {
                            let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0) else {
                                panic!()
                            };
                            Ok(store
                                .borrow()
                                .get(token, role, NativeValueOrigin { node: 2, row })
                                .unwrap()
                                .clone())
                        }
                        Err(_) => Err(provider
                            .take_native_error()
                            .expect("small crypto result or original conversion error")),
                        _ => panic!(),
                    }
                });
                let events = context.events.borrow().clone();
                context.events.borrow_mut().clear();
                let expected = outcome(|| {
                    crate::builtin_ext::crypto::dispatch(
                        &op.name().to_ascii_uppercase(),
                        &values,
                        &context,
                    )
                    .unwrap()
                    .and_then(|v| coerce_function_result(op.name(), Some(&string_ty()), v))
                });
                assert_eq!(actual, expected, "crypto provider {op:?} role={role:?}");
                assert_eq!(events, *context.events.borrow());
                let _ = provider.take_native_error();
                assert!(reply(
                    &mut provider,
                    &mut ctx,
                    &task,
                    arity - 1,
                    Some(
                        insert(&Datum::Null, NativeValueRole::CharInput, 3 + arity - 1, row)
                            .to_vec()
                    )
                )
                .is_err());
                provider.cancel(&task);
                provider.cancel(&task);
            }
            if op == O::Sha2 {
                let task = begin(&mut provider, &mut ctx);
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        Some(
                            insert(
                                &Datum::new_string("value"),
                                NativeValueRole::CharInput,
                                3,
                                row
                            )
                            .to_vec()
                        )
                    ),
                    Ok(HostStep::NeedArg(_))
                ));
                let HostStep::Ready(output) = reply(
                    &mut provider,
                    &mut ctx,
                    &task,
                    1,
                    Some(
                        insert(
                            &Datum::new_string("2".repeat(16 << 10)),
                            NativeValueRole::CharInput,
                            4,
                            row,
                        )
                        .to_vec(),
                    ),
                )
                .unwrap() else {
                    panic!("native SHA2 result expected")
                };
                let ScalarValueRef::Bytes(Some(token)) = output.get_scalar_ref(0) else {
                    panic!("native SHA2 handle")
                };
                assert!(store
                    .borrow()
                    .get(token, role, NativeValueOrigin { node: 2, row })
                    .unwrap()
                    .is_null());
                assert!(provider.take_native_error().is_none());
                assert!(reply(
                    &mut provider,
                    &mut ctx,
                    &task,
                    1,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 4, row).to_vec())
                )
                .is_err());
                provider.cancel(&task);
                let task = begin(&mut provider, &mut ctx);
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                    ),
                    Ok(HostStep::NeedArg(_))
                ));
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        1,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 4, row).to_vec())
                    ),
                    Ok(HostStep::Ready(_))
                ));
                provider.cancel(&task);
            }
            let task = begin(&mut provider, &mut ctx);
            for i in 0..arity {
                let result = reply(
                    &mut provider,
                    &mut ctx,
                    &task,
                    i,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3 + i, row).to_vec()),
                );
                if i + 1 < arity {
                    assert!(matches!(result, Ok(HostStep::NeedArg(_))));
                } else {
                    assert!(matches!(result, Ok(HostStep::Ready(_))));
                }
            }
            provider.cancel(&task);
            if arity == 2 {
                // A valid second capability cannot rehabilitate a first capability
                // invalidated between child replies, even when data was NULL.
                context.events.borrow_mut().clear();
                let task = begin(&mut provider, &mut ctx);
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                    ),
                    Ok(HostStep::NeedArg(_))
                ));
                store.borrow_mut().begin_window().unwrap();
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        1,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 4, row).to_vec())
                    ),
                    Err(LocalError::BindingContract(_))
                ));
                assert!(context.events.borrow().is_empty());
                provider.cancel(&task);
            }
            if op == O::Password {
                for action in [1, 2] {
                    context.warning_action.set(action);
                    context.events.borrow_mut().clear();
                    let task = begin(&mut provider, &mut ctx);
                    let token = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
                    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        reply(&mut provider, &mut ctx, &task, 0, Some(token.to_vec()))
                    }));
                    if action == 1 {
                        assert!(result.is_err());
                    } else {
                        assert!(matches!(result, Ok(Err(LocalError::BindingContract(_)))));
                    }
                    assert_eq!(context.events.borrow().len(), 1);
                    // Warning panic or generation mutation cannot replay the consumed body.
                    assert!(reply(
                        &mut provider,
                        &mut ctx,
                        &task,
                        0,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                    )
                    .is_err());
                    assert_eq!(context.events.borrow().len(), 1);
                    provider.cancel(&task);
                    provider.cancel(&task);
                    let task = begin(&mut provider, &mut ctx);
                    assert!(matches!(
                        reply(
                            &mut provider,
                            &mut ctx,
                            &task,
                            0,
                            Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                        ),
                        Ok(HostStep::Ready(_))
                    ));
                    provider.cancel(&task);
                }
            }
        }
    }
    assert_eq!(rejected, 236);
}

#[test]
fn native_digest_actual_sources_do_not_fallback() {
    let mut failures = vec![];
    for name in crate::tikv::digest_value_tests::NAMES {
        let mut args = vec![literal(
            Datum::VectorFloat32(VectorFloat32::init(0)),
            FieldType::new(FieldTypeCode::VectorFloat32),
        )];
        if name == "SHA2" {
            args.push(literal(Datum::Int(256), ty()));
        }
        let actual = suite(call(name, string_ty(), args));
        let mut input = chunk(&[], &[vec![]]);
        let mut output = output_for(&string_ty());
        let _ = actual.run_with_tikv_batch(&crate::NoColumns, &mut input, &mut output, &[]);
        let route = actual.batch_route_snapshot();
        if (route.refusals, route.fallback) != (0, 0) {
            failures.push((name, route));
        }
    }
    assert!(failures.is_empty(), "crypto actual source {failures:?}");
}

#[test]
fn native_compression_actual_sources_do_not_fallback() {
    let mut failures = vec![];
    for name in crate::tikv::compression_value_tests::NAMES {
        let args = vec![literal(
            Datum::VectorFloat32(VectorFloat32::init(0)),
            FieldType::new(FieldTypeCode::VectorFloat32),
        )];
        let actual = suite(call(name, string_ty(), args));
        let mut input = chunk(&[], &[vec![]]);
        let mut output = output_for(&string_ty());
        let _ = actual.run_with_tikv_batch(&crate::NoColumns, &mut input, &mut output, &[]);
        let route = actual.batch_route_snapshot();
        if (route.refusals, route.fallback) != (0, 0) {
            failures.push((name, route));
        }
    }
    assert!(failures.is_empty(), "crypto actual source {failures:?}");
}

#[test]
fn compression_actual_sources_keep_types_returns_context_and_prefixes() {
    let returns = [
        ty(),
        ty().with_unsigned(true),
        real_ty(),
        FieldType::new(FieldTypeCode::Float),
        string_ty(),
        FieldType::new(FieldTypeCode::NewDecimal)
            .with_flen(65)
            .with_decimal(6),
        FieldType::new(FieldTypeCode::Date),
        FieldType::new(FieldTypeCode::Datetime).with_decimal(6),
        FieldType::new(FieldTypeCode::Duration).with_decimal(6),
        FieldType::new(FieldTypeCode::Json),
        FieldType::new(FieldTypeCode::VectorFloat32),
    ];
    let mut sources = misc_native_source_types();
    for (field, values) in &mut sources {
        if field.code() == FieldTypeCode::VarString {
            let frames: Vec<Vec<u8>> = serde_json::from_str(include_str!(
                "../tikv/testdata/compression_original_n7z.json"
            ))
            .unwrap();
            values.extend(frames.into_iter().map(Datum::Bytes));
        }
    }
    for (field, values) in sources {
        for ret in &returns {
            for name in crate::tikv::compression_value_tests::NAMES {
                for position in 0..3 {
                    let schema = if field.code() == FieldTypeCode::NewDate {
                        vec![]
                    } else {
                        vec![field.clone()]
                    };
                    let rows = if schema.is_empty() {
                        vec![vec![]]
                    } else {
                        values.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>()
                    };
                    let value = if position == 0 || schema.is_empty() {
                        literal(values.last().unwrap().clone(), field.clone())
                    } else {
                        typed_column(0, &field)
                    };
                    let value = if position == 2 {
                        call(
                            "if",
                            field.clone(),
                            vec![int(1), value, literal(Datum::Null, field.clone())],
                        )
                    } else {
                        value
                    };
                    let selection = (0..rows.len())
                        .rev()
                        .chain([0, rows.len() - 1, 0])
                        .collect::<Vec<_>>();
                    for profile in 0..3 {
                        for level in 0..3 {
                            compare_wildcard_source(
                                call(name, ret.clone(), vec![value.clone()]),
                                &schema,
                                &rows,
                                &selection,
                                profile,
                                level,
                            );
                        }
                    }
                }
            }
        }
    }
    for name in crate::tikv::compression_value_tests::NAMES {
        compare_wildcard_source(
            call(
                name,
                string_ty(),
                vec![call("abs", ty(), vec![int(i64::MIN)])],
            ),
            &[],
            &[vec![]],
            &[0, 0],
            0,
            0,
        );
        for computed in [false, true] {
            let field = FieldType::new(FieldTypeCode::NewDecimal);
            let mut value = literal(
                crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                field.clone(),
            );
            if computed {
                value = call(
                    "if",
                    field.clone(),
                    vec![int(1), value, literal(Datum::Null, field)],
                );
            }
            compare_wildcard_source(
                call(name, string_ty(), vec![value]),
                &[],
                &[vec![]],
                &[0],
                0,
                0,
            );
        }
    }
}

#[test]
fn compression_actual_capabilities_warnings_callbacks_resources_and_recovery() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::{
        local::{
            HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, HostTaskId,
            LocalHostServices,
        },
        NativeCompressionOperation as O,
    };
    struct C<'a> {
        store: &'a RefCell<NativeValueStore>,
        events: RefCell<Vec<String>>,
        action: Cell<u8>,
    }
    impl crate::Columns for C<'_> {
        fn get(&self, _: &[String]) -> Option<Datum> {
            panic!("no invented compression source")
        }
        fn ready_value_cache(&self) -> Option<&crate::tikv::ReadyValueCache> {
            panic!("retired compression Ready")
        }
        fn time_zone(&self) -> SessionTimeZone {
            panic!("pure compression cannot read zone")
        }
        fn truncate_level(&self) -> crate::ErrorLevel {
            panic!("pure compression cannot read truncation policy")
        }
        fn append_warning(&self, code: u16, message: &str) {
            let mut store = self.store.borrow_mut();
            self.events
                .borrow_mut()
                .push(format!("warning:{code}:{message}"));
            match self.action.replace(0) {
                1 => panic!("original compression warning panic"),
                2 => store.begin_window().unwrap(),
                _ => (),
            }
        }
    }
    fn outcome(f: impl FnOnce() -> std::result::Result<Datum, EvalError>) -> String {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(v) => format!("{v:?}"),
            Err(p) => format!(
                "PANIC:{:?}",
                p.downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| p.downcast_ref::<&str>().copied())
            ),
        }
    }
    let mut rejected = 0;
    let frames: Vec<Vec<u8>> = serde_json::from_str(include_str!(
        "../tikv/testdata/compression_original_n7z.json"
    ))
    .unwrap();
    for role in [NativeValueRole::Output, NativeValueRole::CharInput] {
        for op in [O::Compress, O::Uncompress, O::Length] {
            let field = projected(&native_bytes_type(), true).unwrap();
            let args = [field.clone()];
            let ret = if op == O::Length { ty() } else { string_ty() };
            let catalog = HostCatalog::for_sql_batch(vec![(
                SqlBatchHostOperation::CompressionNative(op),
                HostSignature {
                    arg_types: args.clone().into(),
                    return_type: field.clone(),
                },
            )])
            .unwrap();
            let slot = catalog.slot(0).unwrap();
            let metadata = [NativeHostMetadata::Arguments(hosts::NativeArguments {
                arguments: (3).into(),
                kernel: hosts::NativeArgumentKernel::Compression {
                    operation: op,
                    probe: None,
                },
                result_type: Some(ret.clone()),
                output_node: 2,
                output_role: Some(role),
            })];
            let store = RefCell::new(NativeValueStore::new().unwrap());
            store.borrow_mut().begin_window().unwrap();
            let row = InputRow {
                occurrence: 0,
                input_row: 0,
            };
            let insert = |value: &Datum, role, node, row| {
                store
                    .borrow_mut()
                    .insert_clone(value, role, NativeValueOrigin { node, row })
                    .unwrap()
            };
            let stale = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
            store.borrow_mut().begin_window().unwrap();
            let mut foreign = NativeValueStore::new().unwrap();
            foreign.begin_window().unwrap();
            let foreign_token = foreign
                .insert_clone(
                    &Datum::Null,
                    NativeValueRole::CharInput,
                    NativeValueOrigin { node: 3, row },
                )
                .unwrap();
            let ctx = C {
                store: &store,
                events: RefCell::new(vec![]),
                action: Cell::new(0),
            };
            let mut provider =
                NativeBatchHosts::new(catalog, &metadata, &ctx).with_native_values(Some(&store));
            let mut eval = EvalContext::default();
            let begin = |p: &mut NativeBatchHosts<'_>, c: &mut EvalContext| {
                let HostStart::Pending { task, request } = p
                    .start(
                        c,
                        HostInvocation {
                            slot,
                            row,
                            arg_types: &args,
                            return_type: &field,
                        },
                    )
                    .unwrap()
                else {
                    panic!()
                };
                assert_eq!(request.index, 0);
                task
            };
            let reply = |p: &mut NativeBatchHosts<'_>,
                         c: &mut EvalContext,
                         task: &HostTaskId,
                         index,
                         token: Option<Vec<u8>>| {
                p.resume(
                    c,
                    task,
                    HostArgReply {
                        index,
                        field_type: &field,
                        values: &VectorValue::from_scalar(&ScalarValue::Bytes(token), 1),
                    },
                )
            };
            let good = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
            let mut corrupt = good.clone();
            corrupt[0] ^= 1;
            let mut short = good.to_vec();
            short.pop();
            let mut long = good.to_vec();
            long.push(0);
            for bad in [
                None,
                Some((corrupt).to_vec()),
                Some((short).to_vec()),
                Some((long).to_vec()),
                Some((stale).to_vec()),
                Some((foreign_token).to_vec()),
                Some((insert(&Datum::Null, NativeValueRole::Output, 3, row)).to_vec()),
                Some((insert(&Datum::Null, NativeValueRole::CharInput, 99, row)).to_vec()),
                Some(
                    (insert(
                        &Datum::Null,
                        NativeValueRole::CharInput,
                        3,
                        InputRow {
                            occurrence: 1,
                            input_row: 0,
                        },
                    ))
                    .to_vec(),
                ),
                Some(
                    (insert(
                        &Datum::Null,
                        NativeValueRole::CharInput,
                        3,
                        InputRow {
                            occurrence: 0,
                            input_row: 1,
                        },
                    ))
                    .to_vec(),
                ),
            ] {
                let task = begin(&mut provider, &mut eval);
                assert!(matches!(
                    reply(
                        &mut provider,
                        &mut eval,
                        &task,
                        0,
                        bad.map(|bytes| bytes.to_vec())
                    ),
                    Err(LocalError::BindingContract(_))
                ));
                assert!(ctx.events.borrow().is_empty());
                assert!(provider.take_native_error().is_none());
                provider.cancel(&task);
                provider.cancel(&task);
                rejected += 1;
            }
            let task = begin(&mut provider, &mut eval);
            assert!(reply(
                &mut provider,
                &mut eval,
                &task,
                1,
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
            )
            .is_err());
            provider.cancel(&task);
            rejected += 1;
            let mut cases = crate::tikv::compression_value_tests::values();
            if op != O::Compress {
                let mut suffix = frames[15].clone();
                suffix.extend_from_slice(&vec![255; 1 << 20]);
                cases.push(Datum::Bytes(suffix));
                let mut header = frames[15].clone();
                header[..4].copy_from_slice(&u32::MAX.to_le_bytes());
                cases.push(Datum::Bytes(header));
                cases.push(Datum::Bytes(vec![255; 1 << 20]));
            }
            for value in cases {
                ctx.events.borrow_mut().clear();
                let task = begin(&mut provider, &mut eval);
                let actual = outcome(|| {
                    match reply(
                        &mut provider,
                        &mut eval,
                        &task,
                        0,
                        Some(insert(&value, NativeValueRole::CharInput, 3, row).to_vec()),
                    ) {
                        Ok(HostStep::Ready(v)) => {
                            let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0) else {
                                panic!()
                            };
                            Ok(store
                                .borrow()
                                .get(token, role, NativeValueOrigin { node: 2, row })
                                .unwrap()
                                .clone())
                        }
                        Err(_) => Err(provider
                            .take_native_error()
                            .expect("bounded compression value or genuine original error")),
                        _ => panic!(),
                    }
                });
                let events = ctx.events.borrow().clone();
                ctx.events.borrow_mut().clear();
                let expected = outcome(|| {
                    crate::builtin_ext::crypto::dispatch(
                        &op.name().to_ascii_uppercase(),
                        &[value],
                        &ctx,
                    )
                    .unwrap()
                    .and_then(|v| coerce_function_result(op.name(), Some(&ret), v))
                });
                assert_eq!(
                    actual, expected,
                    "compression provider {op:?} role={role:?}"
                );
                assert_eq!(events, *ctx.events.borrow());
                let _ = provider.take_native_error();
                assert!(reply(
                    &mut provider,
                    &mut eval,
                    &task,
                    0,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                )
                .is_err());
                provider.cancel(&task);
                provider.cancel(&task);
            }
            if op != O::Compress {
                for action in [1, 2] {
                    ctx.events.borrow_mut().clear();
                    ctx.action.set(action);
                    let task = begin(&mut provider, &mut eval);
                    let token = insert(&Datum::Bytes(vec![1]), NativeValueRole::CharInput, 3, row);
                    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        reply(&mut provider, &mut eval, &task, 0, Some(token.to_vec()))
                    }));
                    if action == 1 {
                        assert!(result.is_err());
                    } else {
                        assert!(matches!(result, Ok(Err(LocalError::BindingContract(_)))));
                    }
                    assert_eq!(ctx.events.borrow().len(), 1);
                    assert!(reply(
                        &mut provider,
                        &mut eval,
                        &task,
                        0,
                        Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                    )
                    .is_err());
                    assert_eq!(ctx.events.borrow().len(), 1);
                    provider.cancel(&task);
                    provider.cancel(&task);
                    let task = begin(&mut provider, &mut eval);
                    assert!(matches!(
                        reply(
                            &mut provider,
                            &mut eval,
                            &task,
                            0,
                            Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                        ),
                        Ok(HostStep::Ready(_))
                    ));
                    provider.cancel(&task);
                }
            }
            ctx.events.borrow_mut().clear();
            let demanding = match op {
                O::Compress => Datum::Bytes(vec![b'x'; 1 << 20]),
                O::Uncompress => Datum::Bytes(
                    tidb_query_expr::native_compress_actual_value(
                        Some(&vec![b'x'; 1 << 20]),
                        8 << 20,
                    )
                    .unwrap()
                    .unwrap(),
                ),
                O::Length => Datum::Decimal(Decimal::from_raw_parts(
                    false,
                    [vec![b'1'], vec![b'0'; 64]].concat(),
                    64,
                    64,
                )),
            };
            let task = begin(&mut provider, &mut eval);
            let HostStep::Ready(value) = reply(
                &mut provider,
                &mut eval,
                &task,
                0,
                Some(insert(&demanding, NativeValueRole::CharInput, 3, row).to_vec()),
            )
            .unwrap() else {
                panic!("cancelled quotas must allow finite compression inputs");
            };
            let ScalarValueRef::Bytes(Some(token)) = value.get_scalar_ref(0) else {
                panic!()
            };
            let actual = store
                .borrow()
                .get(token, role, NativeValueOrigin { node: 2, row })
                .unwrap()
                .clone();
            let expected = crate::builtin_ext::crypto::dispatch(
                &op.name().to_ascii_uppercase(),
                &[demanding],
                &ctx,
            )
            .unwrap()
            .and_then(|v| coerce_function_result(op.name(), Some(&ret), v))
            .unwrap();
            assert_eq!(actual, expected);
            assert!(provider.take_native_error().is_none());
            assert!(ctx.events.borrow().is_empty());
            assert!(reply(
                &mut provider,
                &mut eval,
                &task,
                0,
                Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
            )
            .is_err());
            provider.cancel(&task);
            let task = begin(&mut provider, &mut eval);
            assert!(matches!(
                reply(
                    &mut provider,
                    &mut eval,
                    &task,
                    0,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                ),
                Ok(HostStep::Ready(_))
            ));
            provider.cancel(&task);
            if op == O::Length {
                ctx.events.borrow_mut().clear();
                assert!(matches!(
                    crate::tikv::compression_value::eval(op, &Datum::Bytes(vec![1]), &ctx, 0),
                    Err(EvalError::ExpressionRuntimeFailure(_))
                ));
                assert_eq!(
                    ctx.events.borrow().len(),
                    1,
                    "original short-header warning precedes body refusal"
                );
            }
        }
    }
    assert_eq!(rejected, 66);
}

#[test]
fn eager_scalar_actual_sources_do_not_fallback() {
    let mut failures = vec![];
    for &name in crate::tikv::eager_scalar_value_tests::NAMES {
        let args = crate::tikv::eager_scalar_value_tests::arguments(
            name,
            &Datum::VectorFloat32(VectorFloat32::init(0)),
        )
        .into_iter()
        .map(|v| {
            let f = crate::tikv::misc_identity_value_tests::field(&v);
            literal(v, f)
        })
        .collect();
        let actual = suite(call(name, string_ty(), args));
        let mut input = chunk(&[], &[vec![]]);
        let mut output = output_for(&string_ty());
        let _ = actual.run_with_tikv_batch(&crate::NoColumns, &mut input, &mut output, &[]);
        let route = actual.batch_route_snapshot();
        if (route.refusals, route.fallback) != (0, 0) {
            failures.push((name, route));
        }
    }
    assert!(failures.is_empty(), "eager scalar source {failures:?}");
}

fn compare_eager_source(
    root: Expression,
    schema: &[FieldType],
    rows: &[Vec<Datum>],
    selection: &[usize],
    seed: usize,
    level: usize,
) {
    fn outcome<T: std::fmt::Debug>(f: impl FnOnce() -> T) -> String {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(v) => format!("{v:?}"),
            Err(p) => format!(
                "PANIC:{:?}",
                p.downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| p.downcast_ref::<&str>().copied())
            ),
        }
    }
    let field = snapshot_field_type(root.static_type().unwrap());
    let label = format!("{root:?} {schema:?} seed={seed} level={level} selection={selection:?}");
    let (actual, reference) = (suite(root.clone()), suite(root));
    for enabled in [false, true, false, true] {
        let mut ctx = crate::tikv::wildcard_value_tests::context(1, seed, level);
        ctx.inner.reject = false;
        ctx.inner.enabled.set(enabled);
        let oldctx = crate::tikv::wildcard_value_tests::context(1, seed, level);
        oldctx.inner.enabled.set(enabled);
        let (mut input, mut old) = (chunk(schema, rows), chunk(schema, rows));
        input.set_sel(Some(selection.to_vec()));
        old.set_sel(Some(selection.to_vec()));
        let (mut output, mut expected) = (output_for(&field), output_for(&field));
        assert_eq!(
            outcome(|| actual.run_with_tikv_batch(&ctx, &mut input, &mut output, schema)),
            outcome(|| reference.run(&oldctx, &mut old, &mut expected)),
            "{label} flag={enabled}"
        );
        assert_eq!(
            *ctx.inner.events.borrow(),
            *oldctx.inner.events.borrow(),
            "{label}"
        );
        assert_eq!(output.num_rows(), expected.num_rows(), "{label}");
        assert_eq!(output.column(0), expected.column(0), "{label}");
        let route = actual.batch_route_snapshot();
        assert_eq!(
            (route.refusals, route.fallback),
            (0, 0),
            "{label} {route:?}"
        );
    }
}
#[test]
fn eager_scalar_sources_keep_declared_types_returns_context_selection_and_prefixes() {
    for (field, values) in misc_native_source_types() {
        for ret in crate::tikv::eager_scalar_value_tests::types() {
            for &name in crate::tikv::eager_scalar_value_tests::NAMES {
                for position in 0..3 {
                    let schema = if field.code() == FieldTypeCode::NewDate {
                        vec![]
                    } else {
                        vec![field.clone()]
                    };
                    let rows = if schema.is_empty() {
                        vec![vec![]]
                    } else {
                        values.iter().cloned().map(|v| vec![v]).collect::<Vec<_>>()
                    };
                    let value = if position == 0 || schema.is_empty() {
                        literal(values.last().unwrap().clone(), field.clone())
                    } else {
                        typed_column(0, &field)
                    };
                    let value = if position == 2 {
                        call(
                            "if",
                            field.clone(),
                            vec![int(1), value, literal(Datum::Null, field.clone())],
                        )
                    } else {
                        value
                    };
                    let selection = (0..rows.len())
                        .rev()
                        .chain([0, rows.len() - 1, 0])
                        .collect::<Vec<_>>();
                    let mut args =
                        crate::tikv::eager_scalar_value_tests::arguments(name, &Datum::Null)
                            .into_iter()
                            .map(|v| {
                                let f = crate::tikv::misc_identity_value_tests::field(&v);
                                literal(v, f)
                            })
                            .collect::<Vec<_>>();
                    args[usize::from(name == "JSON_OBJECT")] = value;
                    for profile in 0..3 {
                        for level in 0..3 {
                            compare_eager_source(
                                call(name, ret.clone(), args.clone()),
                                &schema,
                                &rows,
                                &selection,
                                profile,
                                level,
                            );
                        }
                    }
                }
            }
        }
    }
    for name in ["JSON_ARRAY", "JSON_OBJECT"] {
        compare_eager_source(
            call(name, string_ty(), vec![]),
            &[],
            &[vec![]],
            &[0, 0],
            0,
            0,
        );
    }
    for name in [
        "UPPER",
        "JSON_ARRAY",
        "JSON_SET",
        "REPLACE",
        "TO_BASE64",
        "FROM_BASE64",
    ] {
        for computed in [false, true] {
            let field = FieldType::new(FieldTypeCode::NewDecimal);
            let value = literal(
                crate::tikv::misc_identity_value_tests::extra_values().remove(4),
                field.clone(),
            );
            let value = if computed {
                call(
                    "if",
                    field.clone(),
                    vec![int(1), value, literal(Datum::Null, field)],
                )
            } else {
                value
            };
            let mut args = crate::tikv::eager_scalar_value_tests::arguments(name, &Datum::Null)
                .into_iter()
                .map(|v| {
                    let f = crate::tikv::misc_identity_value_tests::field(&v);
                    literal(v, f)
                })
                .collect::<Vec<_>>();
            args[0] = value;
            compare_eager_source(call(name, string_ty(), args), &[], &[vec![]], &[0], 0, 0);
        }
    }
}

#[test]
fn eager_scalar_capabilities_eager_stages_callbacks_consumption_and_recovery() {
    use super::hosts::{NativeBatchHosts, NativeHostMetadata};
    use tidb_query_datatype::codec::data_type::ScalarValueRef;
    use tidb_query_expr::local::{
        HostArgReply, HostInvocation, HostSignature, HostStart, HostStep, HostTaskId,
        LocalHostServices,
    };
    struct C<'a> {
        store: &'a RefCell<NativeValueStore>,
        events: RefCell<Vec<u16>>,
        action: Cell<u8>,
    }
    impl crate::Columns for C<'_> {
        fn get(&self, _: &[String]) -> Option<Datum> {
            panic!("no invented eager operand")
        }
        fn append_warning(&self, code: u16, _: &str) {
            let mut store = self.store.borrow_mut();
            self.events.borrow_mut().push(code);
            match self.action.replace(0) {
                1 => panic!("eager warning unwind"),
                2 => store.begin_window().unwrap(),
                _ => (),
            }
        }
    }
    let mut rejected = 0;
    for optional in [false, true] {
        for role in [NativeValueRole::Output, NativeValueRole::CharInput] {
            for name in [
                "UPPER",
                "JSON_OBJECT",
                "REPLACE",
                "EXPORT_SET",
                "JSON_MERGE",
            ] {
                let actuals = if name == "EXPORT_SET" {
                    vec![
                        Datum::Int(5),
                        Datum::new_string("Y"),
                        Datum::new_string("N"),
                        Datum::new_string(","),
                    ]
                } else {
                    crate::tikv::eager_scalar_value_tests::arguments(
                        name,
                        &Datum::new_string("[1]"),
                    )
                };
                let mut f = ScalarFunction::new(
                    tidb_ast::CiString::new(name),
                    string_ty(),
                    actuals
                        .iter()
                        .cloned()
                        .map(|v| {
                            let t = crate::tikv::misc_identity_value_tests::field(&v);
                            literal(v, t)
                        })
                        .collect(),
                );
                if optional {
                    f.ret_type = None;
                    for arg in &mut f.args {
                        if let Expression::Constant(c) = arg {
                            c.ret_type = None;
                        }
                    }
                }
                let arity = actuals.len();
                let field = projected(&native_bytes_type(), true).unwrap();
                let args = vec![field.clone(); arity];
                let catalog = HostCatalog::for_sql_batch(vec![(
                    SqlBatchHostOperation::EagerValuesNative,
                    HostSignature {
                        arg_types: args.clone().into(),
                        return_type: field.clone(),
                    },
                )])
                .unwrap();
                let slot = catalog.slot(0).unwrap();
                let metadata = [NativeHostMetadata::EagerValues {
                    arguments: (3..3 + arity).collect(),
                    kernel: crate::scalar_function::eager_values::EagerValueKernel::capture(&f),
                    probe: None,
                    result_type: (!optional).then(string_ty),
                    output_node: 2,
                    output_role: role,
                }];
                let store = RefCell::new(NativeValueStore::new().unwrap());
                store.borrow_mut().begin_window().unwrap();
                let row = InputRow {
                    occurrence: 0,
                    input_row: 0,
                };
                let insert = |v: &Datum, role, node, row| {
                    store
                        .borrow_mut()
                        .insert_clone(v, role, NativeValueOrigin { node, row })
                        .unwrap()
                };
                let stale = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
                store.borrow_mut().begin_window().unwrap();
                let mut foreign = NativeValueStore::new().unwrap();
                foreign.begin_window().unwrap();
                let foreign = foreign
                    .insert_clone(
                        &Datum::Null,
                        NativeValueRole::CharInput,
                        NativeValueOrigin { node: 3, row },
                    )
                    .unwrap();
                let ctx = C {
                    store: &store,
                    events: RefCell::new(vec![]),
                    action: Cell::new(0),
                };
                let mut p = NativeBatchHosts::new(catalog.clone(), &metadata, &ctx)
                    .with_native_values(Some(&store));
                let mut eval = EvalContext::default();
                let begin = |p: &mut NativeBatchHosts<'_>, eval: &mut EvalContext| {
                    let HostStart::Pending { task, request } = p
                        .start(
                            eval,
                            HostInvocation {
                                slot,
                                row,
                                arg_types: &args,
                                return_type: &field,
                            },
                        )
                        .unwrap()
                    else {
                        panic!("nonempty eager call")
                    };
                    assert_eq!(request.index, 0);
                    task
                };
                let reply = |p: &mut NativeBatchHosts<'_>,
                             eval: &mut EvalContext,
                             task: &HostTaskId,
                             index,
                             token: Option<Vec<u8>>| {
                    p.resume(
                        eval,
                        task,
                        HostArgReply {
                            index,
                            field_type: &field,
                            values: &VectorValue::from_scalar(&ScalarValue::Bytes(token), 1),
                        },
                    )
                };
                let good = insert(&Datum::Null, NativeValueRole::CharInput, 3, row);
                let mut corrupt = good.clone();
                corrupt[0] ^= 1;
                let mut short = good.to_vec();
                short.pop();
                let mut long = good.to_vec();
                long.push(0);
                for bad in [
                    None,
                    Some((corrupt).to_vec()),
                    Some((short).to_vec()),
                    Some((long).to_vec()),
                    Some((stale).to_vec()),
                    Some((foreign).to_vec()),
                    Some((insert(&Datum::Null, NativeValueRole::Output, 3, row)).to_vec()),
                    Some((insert(&Datum::Null, NativeValueRole::CharInput, 99, row)).to_vec()),
                    Some(
                        (insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3,
                            InputRow {
                                occurrence: 1,
                                input_row: 0,
                            },
                        ))
                        .to_vec(),
                    ),
                    Some(
                        (insert(
                            &Datum::Null,
                            NativeValueRole::CharInput,
                            3,
                            InputRow {
                                occurrence: 0,
                                input_row: 1,
                            },
                        ))
                        .to_vec(),
                    ),
                ] {
                    let task = begin(&mut p, &mut eval);
                    assert!(matches!(
                        reply(&mut p, &mut eval, &task, 0, bad.map(|bytes| bytes.to_vec())),
                        Err(LocalError::BindingContract(_))
                    ));
                    assert!(ctx.events.borrow().is_empty());
                    assert!(p.take_native_error().is_none());
                    p.cancel(&task);
                    p.cancel(&task);
                    rejected += 1;
                }
                let task = begin(&mut p, &mut eval);
                assert!(reply(
                    &mut p,
                    &mut eval,
                    &task,
                    1,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                )
                .is_err());
                p.cancel(&task);
                rejected += 1;
                if arity > 1 {
                    let task = begin(&mut p, &mut eval);
                    assert!(matches!(
                        reply(
                            &mut p,
                            &mut eval,
                            &task,
                            0,
                            Some(insert(&actuals[0], NativeValueRole::CharInput, 3, row).to_vec())
                        )
                        .unwrap(),
                        HostStep::NeedArg(_)
                    ));
                    assert!(reply(
                        &mut p,
                        &mut eval,
                        &task,
                        1,
                        Some(insert(&actuals[1], NativeValueRole::CharInput, 3, row).to_vec())
                    )
                    .is_err());
                    p.cancel(&task);
                    rejected += 1;
                }
                let run = |p: &mut NativeBatchHosts<'_>,
                           eval: &mut EvalContext,
                           task: &HostTaskId| {
                    let mut final_value = None;
                    for (i, value) in actuals.iter().enumerate() {
                        match reply(
                            p,
                            eval,
                            task,
                            i,
                            Some(insert(value, NativeValueRole::CharInput, 3 + i, row).to_vec()),
                        )? {
                            HostStep::NeedArg(r) => assert_eq!(r.index, i + 1),
                            HostStep::NeedArgRow { .. } => {
                                panic!("row provider cannot demand a window row")
                            }
                            HostStep::Ready(v) => {
                                assert_eq!(i + 1, arity);
                                final_value = Some(v);
                            }
                        }
                    }
                    Ok::<_, LocalError>(final_value.unwrap())
                };
                let task = begin(&mut p, &mut eval);
                let result = match run(&mut p, &mut eval, &task) {
                    Ok(v) => v,
                    Err(e) => panic!("{name} {role:?} {e:?} native={:?}", p.take_native_error()),
                };
                let ScalarValueRef::Bytes(Some(token)) = result.get_scalar_ref(0) else {
                    panic!()
                };
                store
                    .borrow()
                    .get(token, role, NativeValueOrigin { node: 2, row })
                    .unwrap();
                assert!(reply(
                    &mut p,
                    &mut eval,
                    &task,
                    0,
                    Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                )
                .is_err());
                p.cancel(&task);
                p.cancel(&task);
                if name == "UPPER" {
                    // An absent declaration does not turn an authenticated SQL NULL
                    // into a missing transport value. Cancellation is terminal, but
                    // cannot cancel a newer task on the same provider.
                    for _ in 0..128 {
                        let old = begin(&mut p, &mut eval);
                        p.cancel(&old);
                        let task = begin(&mut p, &mut eval);
                        p.cancel(&old);
                        let HostStep::Ready(v) = reply(
                            &mut p,
                            &mut eval,
                            &task,
                            0,
                            Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec()),
                        )
                        .unwrap() else {
                            panic!("unary NULL must complete");
                        };
                        let ScalarValueRef::Bytes(Some(token)) = v.get_scalar_ref(0) else {
                            panic!();
                        };
                        assert_eq!(
                            store
                                .borrow()
                                .get(token, role, NativeValueOrigin { node: 2, row })
                                .unwrap(),
                            &Datum::Null
                        );
                        p.cancel(&task);
                    }
                    let task = begin(&mut p, &mut eval);
                    run(&mut p, &mut eval, &task).unwrap();
                    p.cancel(&task);
                }
                if name == "JSON_MERGE" {
                    assert_eq!(*ctx.events.borrow(), vec![1681]);
                    for action in [1, 2] {
                        ctx.events.borrow_mut().clear();
                        ctx.action.set(action);
                        let task = begin(&mut p, &mut eval);
                        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                            run(&mut p, &mut eval, &task)
                        }));
                        if action == 1 {
                            assert!(result.is_err());
                        } else {
                            assert!(matches!(result, Ok(Err(LocalError::BindingContract(_)))));
                        }
                        assert_eq!(*ctx.events.borrow(), vec![1681]);
                        assert!(reply(
                            &mut p,
                            &mut eval,
                            &task,
                            0,
                            Some(insert(&Datum::Null, NativeValueRole::CharInput, 3, row).to_vec())
                        )
                        .is_err());
                        p.cancel(&task);
                        ctx.events.borrow_mut().clear();
                        let task = begin(&mut p, &mut eval);
                        run(&mut p, &mut eval, &task).unwrap();
                        p.cancel(&task);
                        assert_eq!(*ctx.events.borrow(), vec![1681]);
                    }
                }
            }
        }
    }
    assert_eq!(rejected, 236);
}

#[test]
fn eager_scalar_lane_value_cache_is_lazy_and_reuses_exact_closed_workers() {
    struct C {
        calls: Cell<usize>,
    }
    impl crate::Columns for C {
        fn get(&self, _: &[String]) -> Option<Datum> {
            None
        }
        fn ready_value_cache(&self) -> Option<&crate::ReadyValueCache> {
            self.calls.set(self.calls.get() + 1);
            None
        }
    }
    let ctx = C {
        calls: Cell::new(0),
    };
    let cache = crate::ReadyValueCache::new();
    let before = cache.with_fallback_columns(&ctx, |_| {
        Err::<(), _>(EvalError::Unsupported("earlier value failure"))
    });
    assert!(before.is_err());
    assert_eq!(ctx.calls.get(), 0);
    assert_eq!(cache.prepared_worker_count(), 0);
    for n in 1..=2 {
        cache
            .with_fallback_columns(&ctx, |scoped| {
                crate::tikv::evaluate_bytes_in(
                    crate::tikv::EvaluatedBytesOp::Length,
                    scoped,
                    || Ok(Some(b"abc".to_vec())),
                    crate::tikv::EvaluatedBytesResult::into_int_datum,
                )
            })
            .unwrap();
        assert_eq!(ctx.calls.get(), n);
        assert_eq!(cache.prepared_worker_count(), 1);
    }
}

